:root {
  --bg: #0b0f17; --panel: #121826; --panel2: #161d2e; --line: #243049; --ink: #e6ebf5; --mute: #8d99b3;
  --amber: #f4b740; --teal: #34d1a7; --violet: #9b84ff; --rose: #ff7a8a; --slate: #5c6b8a; --dim: #39445c;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, monospace;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--ink); font: 14px/1.45 system-ui, "Segoe UI", Roboto, sans-serif; }
.bar { display: flex; justify-content: space-between; align-items: center; padding: 12px 28px; border-bottom: 1px solid var(--line); }
.brand { font-weight: 700; display: flex; gap: 10px; align-items: center; }
.dot { width: 11px; height: 11px; border-radius: 50%; background: var(--amber); box-shadow: 0 0 0 4px #f4b74033; }
.meta { color: var(--mute); font: 12px var(--mono); }
main { padding: 20px 28px 32px; }
h1 { font-size: 26px; line-height: 1.2; margin: 0 0 8px; letter-spacing: -0.01em; }
h2 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--mute); margin: 0 0 10px; }
h3 { font-size: 13px; margin: 14px 0 6px; color: var(--ink); }
small { color: var(--mute); }
.hero { display: grid; grid-template-columns: 1fr 520px; gap: 20px; }
.formula { color: #c3cbe0; margin: 0 0 12px; max-width: 820px; }
.formula b { color: var(--amber); }
.checks { list-style: none; padding: 0; margin: 0; display: flex; flex-wrap: wrap; gap: 6px; }
.checks li { font-size: 12.5px; padding: 4px 10px 4px 6px; border-radius: 6px; background: #34d1a714; border: 1px solid #34d1a744; }
.checks li b { display: inline-block; width: 18px; text-align: center; color: var(--teal); }
.checks li.bad { background: #ff7a8a18; border-color: #ff7a8a66; }
.checks li.bad b { color: var(--rose); }
.kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; align-content: start; }
.kpi { background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 9px 12px; }
.kpi span { display: block; font-size: 11px; color: var(--mute); text-transform: uppercase; letter-spacing: 0.05em; }
.kpi b { display: block; font: 600 21px var(--mono); margin: 2px 0; }
.kpi em { font-style: normal; font-size: 11.5px; color: var(--mute); }
.evidence { display: grid; grid-template-columns: 1.1fr 1fr 0.95fr; gap: 14px; margin: 18px 0; }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 14px 16px; }
.mini { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.mini th { text-align: left; font-weight: 500; color: var(--mute); font-size: 11px; padding: 3px 4px; border-bottom: 1px solid var(--line); }
.mini th small { display: block; font-size: 10px; }
.mini td { padding: 5px 4px; border-bottom: 1px solid #1d263a; font-family: var(--mono); font-size: 12px; }
.mini td:first-child { font-family: inherit; }
.kept { color: var(--teal); font-weight: 600; }
.drop { color: var(--rose); }
.note { color: var(--mute); font-size: 12px; margin: 8px 0; }
.chart { width: 100%; height: auto; display: block; background: #0e1420; border-radius: 6px; }
.chart .pd { fill: #6f7d9c; opacity: 0.7; }
