.legend .sum { border-top: 1px solid var(--line); margin-top: 4px; padding-top: 5px; font-weight: 600; color: var(--teal); }
.big { font: 600 28px var(--mono); color: var(--amber); margin: 4px 0; }
.big small { display: block; font: 12px system-ui, sans-serif; color: var(--mute); margin-top: 4px; }
.tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--line); margin-bottom: 12px; }
