.filters .check input { min-width: 0; }
.count { margin-left: auto; color: var(--mute); font: 12px var(--mono); padding-bottom: 8px; }
.split { display: grid; grid-template-columns: 1fr 410px; gap: 16px; align-items: start; }
.tablewrap { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; overflow: auto; max-height: 760px; }
#table { width: 100%; border-collapse: collapse; }
