#table th.asc::after { content: " ▲"; color: var(--amber); }
#table th.desc::after { content: " ▼"; color: var(--amber); }
#table td { padding: 7px 8px; font-size: 13px; border-top: 1px solid #1d263a; vertical-align: middle; }
#table tr[data-s] { cursor: pointer; }
#table tr.sel td { background: #f4b74014; }
#table tr.sel td:first-child { box-shadow: inset 3px 0 var(--amber); }
.num { font-family: var(--mono); text-align: right; white-space: nowrap; }
.up { color: var(--teal); }
.down { color: var(--rose); }
.tag { font-size: 10px; padding: 1px 5px; border-radius: 3px; margin-left: 6px; vertical-align: 1px; }
.tag.w { color: var(--violet); border: 1px solid #9b84ff88; }
.val { min-width: 170px; font-family: var(--mono); }
.val b { display: block; font-size: 13.5px; }
.val small { font-size: 11px; }
.rng { display: block; position: relative; height: 5px; background: #1d263a; border-radius: 3px; margin-bottom: 4px; }
.rng i { position: absolute; top: 0; bottom: 0; background: #f4b74055; border-radius: 3px; }
.rng b { position: absolute; top: -2px; width: 3px; height: 9px; background: var(--amber); }
.pill { font: 700 10.5px var(--mono); padding: 2px 7px; border-radius: 4px; letter-spacing: 0.04em; }
.pill.FARM { background: #34d1a722; color: var(--teal); border: 1px solid #34d1a766; }
.pill.THIN { background: #f4b74022; color: var(--amber); border: 1px solid #f4b74066; }
.pill.SKIP { background: #ff7a8a1c; color: var(--rose); border: 1px solid #ff7a8a55; }
.detail { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 16px 18px; position: sticky; top: 12px; }
.detail h2 { font-size: 22px; text-transform: none; letter-spacing: 0; color: var(--ink); margin: 2px 0 8px; }
.kicker { margin: 0; color: var(--mute); font-size: 12px; }
.chips { display: flex; flex-wrap: wrap; gap: 5px; margin: 0 0 6px; }
.chips span { font-size: 11.5px; padding: 2px 8px; border-radius: 10px; background: var(--panel2); border: 1px solid var(--line); }
.chips .none { color: var(--violet); border-color: #9b84ff66; }
.build { width: 100%; border-collapse: collapse; font-size: 13px; }
.build td { padding: 5px 0; border-bottom: 1px dashed #26314a; }
.build td:last-child { text-align: right; font-family: var(--mono); }
.build small { display: block; font-size: 11px; }
.build .sub td { color: #c3cbe0; }
.build .tot td { font-weight: 700; color: var(--amber); font-size: 15px; border-bottom: 1px solid var(--line); }
.econ { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.econ div { background: var(--panel2); border-radius: 6px; padding: 6px 8px; }
.econ span { display: block; font-size: 10.5px; color: var(--mute); text-transform: uppercase; }
.econ b { font-family: var(--mono); font-size: 14px; }
.be { font-size: 12.5px; color: var(--mute); margin: 8px 0; }
.be b { color: var(--ink); font-family: var(--mono); }
.steps { margin: 6px 0 0; padding-left: 20px; font-size: 12.5px; color: #cfd6e6; }
.steps li { margin-bottom: 5px; }
.foot { color: var(--mute); font-size: 11.5px; margin-top: 18px; max-width: 1100px; }
.focus .evidence, .focus .kpis, .focus .formula { display: none; }
.focus .hero { grid-template-columns: 1fr; margin-bottom: 14px; }
.focus h1 { font-size: 20px; }
.focus .tablewrap { max-height: none; }
@media (max-width: 1100px) { .hero, .evidence, .split { grid-template-columns: 1fr; } }
