    const pool = all.filter((x) => x.p.listed_at && (x.group === 'traded' || x.group === 'tokenNoCap' || x.group === 'watch' || x.group === 'radar'))
      .map((x) => ({ slug: x.p.slug, listed: x.p.listed_at, f: x.f, y: x.token ? 1 : 0 }));
